# 本行用途：base_versions是读集合版本，updates是写集合；读集合可比写集合大。；例如修改交付时间还依赖准备步骤，则两者都应记版本，但只写入交付步骤。
# 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
@dataclass(frozen=True)
# 逐行说明：定义PlanPatch类，组织同一职责的数据和方法；实例状态独立，Protocol仅声明接口而非提供实现。
# 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
class PlanPatch:
    """base_versions为相关读集合，updates为写集合；无关任务不随补丁重置。"""
    # 生成补丁时读取的相关片段版本，包括只读但影响可行性的片段。
    # 逐行说明：“片段名→整数版本号”，如准备任务:2、交付任务:5。记录生成补丁时所有读取依据；只读但影响可行性的准备任务也要记，valid据此防止旧条件方案被应用。int是第几版，不是任务内容。
    # 本行用途：生成补丁时读取的相关片段版本，包括只读但影响可行性的片段。
    # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
    base_versions: dict[str, int]
    # 实际覆盖的片段及新内容；没有出现在这里的任务不会被重做。
    # 逐行说明：“片段名→新内容”；内容可为列表、字典或计划对象，所以用Any而非int。apply只覆盖这些键，读过但没写入的任务保留；Any不免除插件业务校验。
    # 本行用途：实际覆盖的片段及新内容；没有出现在这里的任务不会被重做。
    # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
    updates: dict[str, Any]


# 逐行说明：定义SegmentedPlan类，组织同一职责的数据和方法；实例状态独立，Protocol仅声明接口而非提供实现。
# 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
class SegmentedPlan:
    """按任务片段维护内容与版本，支持局部乐观并发检查。"""
    # 初始化本实例的状态；self字段属于当前对象，不是所有Agent共享的全局变量。
    # 逐行说明：定义__init__方法及调用参数；self代表当前对象。调用时才执行下方步骤，职责见原有用途注释。
    # 本行用途：初始化本实例的状态；self字段属于当前对象，不是所有Agent共享的全局变量。
    # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
    def __init__(self, segments):
        # 逐行说明：计算“copy.deepcopy(segments)”并保存到self.segments；self字段属于本人成员，其余为本次调用局部变量；赋值不自动发送消息或应用计划。
        # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
        self.segments = copy.deepcopy(segments)
        # 把segments的每个键映射到初始版本0；不是复制计划内容，而是建立单独版本表。
        # 逐行说明：计算“dict.fromkeys(segments, 0)”并保存到self.versions；self字段属于本人成员，其余为本次调用局部变量；赋值不自动发送消息或应用计划。
        # 本行用途：把segments的每个键映射到初始版本0；不是复制计划内容，而是建立单独版本表。
        # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
        self.versions = dict.fromkeys(segments, 0)

    # 检查补丁非空、每个写入键都带读取版本、所有读取版本与当前一致。
    # 这是乐观并发控制：生成时不锁整个计划，安装前用版本发现条件是否已经变化。
    # 逐行说明：定义valid方法及调用参数；self代表当前对象。调用时才执行下方步骤，职责见原有用途注释。
    # 本行用途：检查补丁非空、每个写入键都带读取版本、所有读取版本与当前一致。；这是乐观并发控制：生成时不锁整个计划，安装前用版本发现条件是否已经变化。
    # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
    def valid(self, patch):
        # 写入前必须验证所有相关读取，而不是仅验证本次写入的片段。
        # 逐行说明：返回“(bool(patch.updates) and set(patch.updates) <= set(patch.base_versions)”并结束调用；只给出本阶段结果，不替代其他阶段的约束校验。
        # 本行用途：写入前必须验证所有相关读取，而不是仅验证本次写入的片段。
        # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
        return (bool(patch.updates) and set(patch.updates) <= set(patch.base_versions)
                # 逐行说明：这是上方表达式的续行：“and all(key in self.versions and self.versions[key] == version”；与前后行共同组成条件、字典或推导式，不是独立执行步骤。
                # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
                and all(key in self.versions and self.versions[key] == version
                        # 逐行说明：按“for key, version in patch.base_versions.items()))”逐项处理；逗号变量解包当前元素，只遍历明确给出的集合，不自动访问队友私有状态。
                        # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
                        for key, version in patch.base_versions.items()))

    # 先完成整份补丁的读取版本校验，再开始写入，避免校验失败时留下部分修改。
    # 深拷贝updates后只迭代写集合，无关任务片段内容和版本都不会改变。
    # 逐行说明：定义apply方法及调用参数；self代表当前对象。调用时才执行下方步骤，职责见原有用途注释。
    # 本行用途：先完成整份补丁的读取版本校验，再开始写入，避免校验失败时留下部分修改。；深拷贝updates后只迭代写集合，无关任务片段内容和版本都不会改变。
    # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
    def apply(self, patch):
        # 深拷贝后安装，避免调用方继续修改补丁而改变已确认的本地计划。
        # 逐行说明：检查条件“if not self.valid(patch)”；根据当前状态决定进入本分支或继续循环，不满足则跳过或退出；and/or短路，不会无条件执行后续步骤。
        # 本行用途：深拷贝后安装，避免调用方继续修改补丁而改变已确认的本地计划。
        # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
        if not self.valid(patch):
            # 逐行说明：抛出“ValueError("Local patch read/write versions are stale or incomplete")”并终止当前调用，暴露前提不满足，不让非法方案继续执行。
            # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
            raise ValueError("Local patch read/write versions are stale or incomplete")
        # 逐行说明：计算“copy.deepcopy(patch.updates)”并保存到updates；self字段属于本人成员，其余为本次调用局部变量；赋值不自动发送消息或应用计划。
        # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
        updates = copy.deepcopy(patch.updates)
        # items产生键值对，由左侧两个变量解包；只遍历补丁写集合，不会重置无关任务。
        # 逐行说明：按“for key, value in updates.items()”逐项处理；逗号变量解包当前元素，只遍历明确给出的集合，不自动访问队友私有状态。
        # 本行用途：items产生键值对，由左侧两个变量解包；只遍历补丁写集合，不会重置无关任务。
        # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
        for key, value in updates.items():
            # 逐行说明：计算“value”并保存到self.segments[key]；self字段属于本人成员，其余为本次调用局部变量；赋值不自动发送消息或应用计划。
            # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
            self.segments[key] = value
            # 读取当前版本、加1再写回，使持有旧版本的后续补丁无法通过valid。
            # 逐行说明：执行“self.versions[key] += 1”并写回，推进指定版本、计数或选项索引，不重置其他对象。
            # 本行用途：读取当前版本、加1再写回，使持有旧版本的后续补丁无法通过valid。
            # 报告原文：“本地计划按任务片段保存。补丁记录读取过的相关片段版本，以及确实需要写入的内容。安装前先检查读取版本；通过后只更新写集合并递增对应版本，无关片段保持不变。”
            self.versions[key] += 1


