# 传输层不制定计划，只接收和投递Message；可靠同步投递由当前实验驱动保证。
# 逐行说明：定义Transport类，组织同一职责的数据和方法；实例状态独立，Protocol仅声明接口而非提供实现。
# 本行用途：传输层不制定计划，只接收和投递Message；可靠同步投递由当前实验驱动保证。
