    # 是否较短按JSON字符串长度判断，不等于UTF-8网络字节；完整报文也附版本供下一次对齐。
    # 将一条消息加入指定接收者的传输通道，不直接执行对方私有方法。
    # 逐行说明：执行“def send(self, message: Message) -> None: ...”；发送调用仅投递消息，日志仅作审计，缓存清理防止复用旧状态，具体业务效果由被调方法负责。
    # 本行用途：只在respond且启用delta_messages时尝试差量；其他消息保持原样。；差量基于发给同一接收者的上一版公开内容；字典副本隔离后续原地修改。；是否较短按JSON字符串长度判断，不等于UTF-8网络字节；完整报文也附版本供下一次对齐。；将一条消息加入指定接收者的传输通道，不直接执行对方私有方法。
    # 报告原文：“任务接口负责观察、生成候选、生成响应、检查组合、核验与安装局部方案；消息接口负责按收件人投递；环境时钟负责交换阶段与执行阶段推进。”
    def send(self, message: Message) -> None: ...
