    # 逐行说明：执行“def receive(self, receiver: str) -> list[Message]: ...”；发送调用仅投递消息，日志仅作审计，缓存清理防止复用旧状态，具体业务效果由被调方法负责。
    # 本行用途：取出指定成员的待收消息；收件箱管理由传输实现负责。
