        # 本行用途：保存本成员已知提案，供后续消息核验owner与participants。
        # 报告原文：“核心流程为：观察状态，检查原安排是否有效，必要时提出候选，收集相关方响应，检查组合，确认局部补丁，执行近期动作，再读取真实反馈。”
        self.proposals = {}
